const passport = require('passport');
const SamlStrategy = require('passport-saml').Strategy;
const { db } = require('../lib/db');

passport.use('saml-tenant', new SamlStrategy({
  path: '/auth/saml/callback/:tenantId',
  entryPoint: process.env.SAML_ENTRY_POINT,
  issuer: 'enterprise-app'
}, async (req, profile, done) => {
  const { tenantId } = req.params;
  const userEmail = profile.nameID || profile.email;

  const tenantConfig = await db.query(
    'SELECT idp_entity_id, idp_cert FROM tenant_saml_configs WHERE tenant_id = $1',
    [tenantId]
  );
  if (tenantConfig.rowCount === 0 || tenantConfig.rows[0].idp_entity_id !== profile.issuer) {
    return done(null, false, { message: 'Unauthorized: SAML assertion issuer does not match tenant IdP configuration' });
  }

  const user = await db.query(
    'SELECT * FROM tenant_users WHERE email = $1 AND tenant_id = $2',
    [userEmail, tenantId]
  );
  if (user.rowCount === 0) {
    return done(null, false, { message: 'User not registered in tenant' });
  }

  return done(null, user.rows[0]);
}));
